package io.updatecanary.probe;import java.lang.reflect.*;import java.nio.file.*;import java.util.*;import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.permissions.Permission;import org.bukkit.plugin.*;import org.bukkit.plugin.java.JavaPlugin;public final class CanaryProbePlugin extends JavaPlugin{public void onEnable(){try{Path out=Path.of(System.getProperty("canary.probe.output","canary-probe.json"));Server s=getServer();List<ProbeSnapshotWriter.PluginState>ps=Arrays.stream(s.getPluginManager().getPlugins()).map(p->new ProbeSnapshotWriter.PluginState(p.getName(),p.getDescription().getVersion(),p.isEnabled())).toList();List<ProbeSnapshotWriter.PermissionState>per=s.getPluginManager().getPermissions().stream().sorted(Comparator.comparing(Permission::getName)).map(p->new ProbeSnapshotWriter.PermissionState(p.getName(),String.valueOf(p.getDefault()))).toList();List<ProbeSnapshotWriter.CommandState>cmds=new ArrayList<>();boolean complete=true;try{Field f=s.getClass().getDeclaredField("commandMap");f.setAccessible(true);Object cm=f.get(s);Method m=cm.getClass().getMethod("getKnownCommands");Object raw=m.invoke(cm);if(raw instanceof Map<?,?> map)for(var e:map.entrySet()){if(e.getValue() instanceof Command c){String owner=c instanceof PluginIdentifiableCommand pc?pc.getPlugin().getName():"";cmds.add(new ProbeSnapshotWriter.CommandState(String.valueOf(e.getKey()),owner,c.getPermission()));}}}catch(Exception e){complete=false;}new ProbeSnapshotWriter().write(out,new ProbeSnapshotWriter.ServerInfo(s.getName(),s.getBukkitVersion().split("-R",2)[0],System.getProperty("java.version")),ps,cmds,per,complete);}catch(Exception e){getLogger().severe("Canary probe failed: "+e.getClass().getSimpleName()+": "+e.getMessage());}}}
